$b = "/Users/kangkukjin/Desktop/AI/indiebizOS/outputs/long_sentence_imagination/2026-10-08_36회차/ai/base"
$r = [self:read]{path: f"${b}/result.json"}
$m = [self:read]{path: f"${b}/report.md"}
$l = [self:list]{path: $b}
$p = [self:list]{path: "/Users/kangkukjin/Desktop/AI/indiebizOS/outputs/long_sentence_imagination/2026-10-08_36회차/ai"}
return {result: $r.data, report: $m.text, base_list: $l >> [table:select]{columns:["name","size","is_dir"]}, ai_list: $p >> [table:select]{columns:["name","is_dir"]}}

$old = $입력.result
$d = "/Users/kangkukjin/Desktop/AI/indiebizOS/outputs/long_sentence_imagination/2026-10-08_36회차/ai/presentation"
[def:찾기]($kits,$id){ return ($kits >> [table:filter]{where:($k)=>$k.id==$id})[0] }
$order = ["gamma","beta","alpha"]
$kits = $order >> [table:each]{ return [fn:찾기]{kits:$old.kits,id:$it} }
$new = {title:"교육 자료 최종 인계", kits:$kits}
[def:행]($k){
  $miss = len($k.missing)==0 ? "없음" : join($k.missing,", ")
  $zip = $k.archive == null ? "(생성 안 함)" : $k.archive
  return f"| ${$k.id} | ${$k.status} | ${len($k.files)} | ${$k.verified_count} | ${$miss} | ${$zip} |"
}
$rows = $kits >> [table:each]{ return [fn:행]{k:$it} }
$md = join([
 "# 교육 자료 최종 인계", "",
 "| 반 | 상태 | 필요 수 | 검증 수 | 누락 | ZIP 경로 |",
 "|---|---|---|---|---|---|",
 join($rows,"\n"), "",
 "- 이 문서는 앞 인계(base/result.json, 제목 '교육 자료 인계 v1')의 제목과 반 순서만 바꾼 개정판이다. 자료와 ZIP 내용은 바뀌지 않았다.",
 "- 상태·필요 파일 목록·누락·검증 수·ZIP 경로는 base/result.json 값을 그대로 옮겼다. ZIP은 재압축·복사하지 않았으며 위 경로는 base 폴더의 원래 파일이다.",
 "- 검증 근거(앞 인계): ZIP을 다시 열어 항목 이름 집합 = 필요 목록, 중복 0, 디렉터리 항목 0, 항목별 sha256 = 원본 sha256 을 전건 확인했다(base/work/verify_zip.py).",
 "- gamma 반은 gamma/lesson07.txt 누락으로 blocked이며 ZIP이 없다.",
 "- 필요 파일 전체 목록은 같은 폴더의 result.json kits[].files 에 있다.", ""],"\n")
[self:mkdir]{path:$d}
[self:write]{path:f"${$d}/result.json", content:json($new)}
[self:write]{path:f"${$d}/report.md", content:$md}
$rj = ([self:read]{path:f"${$d}/result.json"}).data
$rm = ([self:read]{path:f"${$d}/report.md"}).text
$ids = $rj.kits >> [table:each]{ return $it.id }
$same = $rj.kits >> [table:each]{
  $o = [fn:찾기]{kits:$old.kits,id:$it.id}
  return {id:$it.id, status:$it.status==$o.status, archive:$it.archive==$o.archive, files:$it.files==$o.files, missing:$it.missing==$o.missing, verified:$it.verified_count==$o.verified_count}
}
return {title:$rj.title, ids:$ids, same:$same, report:$rm}
